package com.badspell.progression;

import com.badspell.research.ResearchRules;

import com.badspell.content.*;
import com.badspell.formula.*;
import com.badspell.server.*;
import com.badspell.network.Packets;
import java.util.*;
import java.util.function.Consumer;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.event.RegisterGameTestsEvent;
import net.neoforged.neoforge.registries.DeferredRegister;

/** Actual server-side inventories, payment, permission and persistence. Fresh survival knowledge. */
public final class ResearchGameTests {
    private static final DeferredRegister<Consumer<GameTestHelper>> FUNCTIONS=DeferredRegister.create(Registries.TEST_FUNCTION,"badspell");
    private static final List<String> NAMES=new ArrayList<>();
    private static void test(String name,Consumer<GameTestHelper> body){NAMES.add(name);FUNCTIONS.register(name,()->body);}
    private static ServerPlayer player(GameTestHelper h){var p=new net.neoforged.neoforge.common.util.FakePlayer(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"ResearchQA"));ResearchProgress.initialize(p);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ModItems.FORMULA_BOOK.get()));MagicActions.openBook(p,InteractionHand.MAIN_HAND);p.getInventory().setItem(1,new ItemStack(ModItems.FIELD_CELL.get()));p.getInventory().setItem(2,new ItemStack(Items.PAPER,10));p.getInventory().setItem(3,new ItemStack(ModContent.item("field_crystal_shard"),10));return p;}
    private static int charge(ServerPlayer p){return p.getInventory().getItem(1).getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getIntOr("badspell_fl",100);}
    private static int ink(ServerPlayer p){return p.getMainHandItem().getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getIntOr("badspell_ink",0);}
    private static List<Integer> answer(ServerPlayer p,String rune){return ResearchRules.solution(ResearchActions.seed(p),rune).stream().map(Enum::ordinal).toList();}
    private static int count(ServerPlayer p,Item item){int count=0;for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i).is(item))count+=p.getInventory().getItem(i).getCount();return count;}
    static {
        test("m2_fresh_and_isolated",h->{var p=player(h);var other=player(h);h.assertTrue(ResearchProgress.keys(ResearchProgress.data(p),"known").equals(ResearchRules.BASICS),"Only bootstrap knowledge");ResearchProgress.learn(p,"badspell:circle");h.assertTrue(!ResearchProgress.knows(other,"badspell:circle"),"No automatic sharing");h.succeed();});
        test("m2_prepare_and_payment",h->{var p=player(h);h.assertTrue(ResearchActions.perform(p,1,"badspell:circle",List.of()).equals("prepared"),"Prepare");h.assertTrue(count(p,ModItems.RUNE_FRAGMENT.get())==1&&count(p,Items.PAPER)==9&&count(p,ModContent.item("field_crystal_shard"))==9,"Real finite ingredients");int fl=ResearchRules.fieldCost("badspell:circle"),ink=ResearchRules.inkCost("badspell:circle");h.assertTrue(ResearchActions.perform(p,2,"badspell:circle",answer(p,"badspell:circle")).equals("learned"),"Correct signature");h.assertTrue(charge(p)==100-fl&&ink(p)==64-ink&&count(p,ModItems.RUNE_FRAGMENT.get())==0,"Atomic exact payment");int before=charge(p);h.assertTrue(ResearchActions.perform(p,2,"badspell:circle",answer(p,"badspell:circle")).equals("already")&&charge(p)==before,"Replay has no charge or duplicate");h.succeed();});
        test("m2_wrong_solution_preserves_fragment",h->{var p=player(h);ResearchActions.perform(p,1,"badspell:circle",List.of());var bad=new ArrayList<>(answer(p,"badspell:circle"));bad.set(0,(bad.get(0)+1)%Value.Type.values().length);h.assertTrue(ResearchActions.perform(p,2,"badspell:circle",bad).equals("mismatch"),"Wrong ports rejected");h.assertTrue(!ResearchProgress.knows(p,"badspell:circle")&&count(p,ModItems.RUNE_FRAGMENT.get())==1&&charge(p)==90&&ink(p)==62,"Failed measurement costs specified resources but preserves sample");h.succeed();});
        test("m2_insufficient_resources_atomic",h->{var p=player(h);ResearchActions.perform(p,1,"badspell:circle",List.of());CustomData.update(DataComponents.CUSTOM_DATA,p.getInventory().getItem(1),t->t.putInt("badspell_fl",0));h.assertTrue(ResearchActions.perform(p,2,"badspell:circle",answer(p,"badspell:circle")).equals("need_energy"),"No energy");h.assertTrue(count(p,ModItems.RUNE_FRAGMENT.get())==1&&ink(p)==64&&!ResearchProgress.knows(p,"badspell:circle"),"No partial debit");h.succeed();});
        test("m2_unsigned_fragment_rejected",h->{var p=player(h);var fragment=new ItemStack(ModItems.RUNE_FRAGMENT.get());CustomData.update(DataComponents.CUSTOM_DATA,fragment,t->{t.putString("rune","badspell:circle");t.putString("author","fragment");t.putString("seal","forged");});p.getInventory().setItem(5,fragment);h.assertTrue(ResearchActions.perform(p,2,"badspell:circle",answer(p,"badspell:circle")).equals("need_fragment")&&charge(p)==100,"Arbitrary rune NBT cannot authorize learning");h.succeed();});
        test("m2_deliberate_teaching",h->{var p=player(h);var pupil=player(h);ResearchProgress.learn(p,"badspell:circle");h.assertTrue(ResearchActions.perform(p,3,"badspell:circle",List.of()).equals("shared")&&charge(p)==90&&ink(p)==62,"Teacher pays");ItemStack folio=ItemStack.EMPTY;for(int i=0;i<p.getInventory().getContainerSize();i++)if(p.getInventory().getItem(i).is(ModItems.TEACHING_FOLIO.get())){folio=p.getInventory().removeItemNoUpdate(i);break;}h.assertTrue(!folio.isEmpty(),"Physical transfer object");pupil.setItemInHand(InteractionHand.OFF_HAND,folio);ResearchActions.use(pupil,InteractionHand.OFF_HAND,true);h.assertTrue(ResearchProgress.knows(pupil,"badspell:circle")&&pupil.getOffhandItem().isEmpty(),"Lesson consumes only on intentional use");h.succeed();});
        test("m2_unknown_export_denied",h->{var p=player(h);var book=p.getMainHandItem();try{var old=MagicActions.read(book);var template=ExampleFormulas.template("frost_push",p.getUUID(),new Value.Position(h.getLevel().dimension().identifier().toString(),0,64,0));var proposed=new Formula(old.id(),p.getUUID(),old.revision(),template.title(),template.nodes(),template.edges(),template.output(),template.energyBudget());MagicActions.handle(p,new Packets.BookAction(0,0,FormulaCodec.encode(proposed)));h.assertTrue(MagicActions.read(book).revision()==old.revision()&&ink(p)==64,"Unknown graph cannot be saved by forged packet");}catch(java.io.IOException e){throw new IllegalStateException(e);}h.succeed();});
        test("m2_discoveries_and_station_proofs",h->{var p=player(h);ResearchProgress.observe(p);ResearchProgress.station(p,"arcane_workbench");ResearchProgress.station(p,"crystal_grinder");ResearchProgress.formula(p);var d=ResearchProgress.data(p);h.assertTrue(ResearchProgress.keys(d,"discovered").contains("badspell:field_crystal_shard")&&ResearchRules.tier(ResearchProgress.keys(d,"discovered"),ResearchProgress.keys(d,"stations"),0,true)==1,"Actual discoveries and proof-based tier");h.succeed();});
        test("m2_profile_roundtrip_and_death",h->{var p=player(h);ResearchProgress.learn(p,"badspell:circle");ResearchProgress.station(p,"crystal_grinder");var copy=ResearchProgress.data(p).copy();var respawn=player(h);ResearchProgress.clone(new net.neoforged.neoforge.event.entity.player.PlayerEvent.Clone(respawn,p,true));h.assertTrue(ResearchProgress.data(respawn).equals(copy),"Death clone preserves exact private state");p.getPersistentData().put(ResearchProgress.KEY,copy.copy());ResearchProgress.initialize(p);h.assertTrue(ResearchProgress.knows(p,"badspell:circle"),"Initialization never resets existing persistent data");h.succeed();});
        test("m2_legacy_inactive_glove_migration",h->{var p=new net.neoforged.neoforge.common.util.FakePlayer(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"LegacyResearch"));var glove=new ItemStack(ModItems.RUNE_GLOVE.get());try{com.badspell.item.GloveFormulas.importSnapshot(glove,ExampleFormulas.light(p.getUUID()),p.getUUID());com.badspell.item.GloveFormulas.cycle(glove,1,p.getUUID());com.badspell.item.GloveFormulas.importSnapshot(glove,ExampleFormulas.template("frost_push",p.getUUID(),new Value.Position("minecraft:overworld",0,64,0)),p.getUUID());com.badspell.item.GloveFormulas.cycle(glove,-1,p.getUUID());}catch(java.io.IOException e){throw new IllegalStateException(e);}p.getInventory().setItem(1,glove);ResearchProgress.initialize(p);h.assertTrue(ResearchProgress.knows(p,"badspell:cold")&&ResearchProgress.knows(p,"badspell:push"),"One-time migration includes inactive owned slots");var before=ResearchProgress.keys(ResearchProgress.data(p),"known");p.getInventory().setItem(2,ResearchActions.artifact(p,"badspell:heal",true));ResearchProgress.initialize(p);h.assertTrue(ResearchProgress.keys(ResearchProgress.data(p),"known").equals(before),"Later inventory content never repeats migration");h.succeed();});
        test("m2_knowledge_stamp_matches_exact_snapshot",h->{var p=player(h);try{var f=MagicActions.read(p.getMainHandItem());h.assertTrue(ResearchProgress.authorized(p.getMainHandItem(),f),"Opened known book is approved for offline engraving");var changed=new Formula(f.id(),f.owner(),f.revision()+1,f.title(),f.nodes(),f.edges(),f.output(),f.energyBudget());h.assertTrue(!ResearchProgress.authorized(p.getMainHandItem(),changed),"Any revision change invalidates approval");}catch(java.io.IOException e){throw new IllegalStateException(e);}h.succeed();});
        test("m2_all_samples_resolve",h->{for(var family:ResearchRules.FAMILIES)h.assertTrue(BuiltInRegistries.ITEM.getValue(Identifier.parse(family.sample()))!=Items.AIR,"Every research path has a registered real sample: "+family.sample());h.succeed();});
    }
    public static void register(IEventBus bus){FUNCTIONS.register(bus);bus.addListener(ResearchGameTests::tests);}
    private static void tests(RegisterGameTestsEvent event){var env=event.registerEnvironment(Identifier.fromNamespaceAndPath("badspell","m2_research"));for(String name:NAMES){var id=Identifier.fromNamespaceAndPath("badspell",name);event.registerTest(id,new FunctionGameTestInstance(ResourceKey.create(Registries.TEST_FUNCTION,id),new TestData<>(env,Identifier.fromNamespaceAndPath("badspell","test_room"),200,0,true)));}}
}
